import{_ as a,o as t,c as n,a2 as s}from"./chunks/framework.RycU2wFZ.js";const u=JSON.parse('{"title":"AgentPay vs. x402","description":"x402 answers how to pay; AgentPay answers whether payment should be allowed. Learn how they divide responsibilities and work together.","frontmatter":{"title":"AgentPay vs. x402","description":"x402 answers how to pay; AgentPay answers whether payment should be allowed. Learn how they divide responsibilities and work together."},"headers":[],"relativePath":"learn/03-infra-map/agentpay-vs-x402.md","filePath":"learn/03-infra-map/agentpay-vs-x402.md","lastUpdated":1792595354000}'),o={name:"learn/03-infra-map/agentpay-vs-x402.md"};function r(i,e,l,p,d,c){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="agentpay-vs-x402" tabindex="-1">AgentPay vs. x402 <a class="header-anchor" href="#agentpay-vs-x402" aria-label="Permalink to &quot;AgentPay vs. x402&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Experimental Project</p><p>AgentPay has not undergone an independent security audit. Do not use it with real production funds.</p></div><h2 id="in-a-nutshell" tabindex="-1">In a nutshell <a class="header-anchor" href="#in-a-nutshell" aria-label="Permalink to &quot;In a nutshell&quot;">​</a></h2><blockquote><p><strong>x402 answers “How do I pay?” AgentPay answers “Should I pay?”</strong></p></blockquote><p>x402 is an open protocol that lets HTTP requests carry payment information. AgentPay is a control layer between an agent and that protocol: the protocol carries out the payment exchange; the control layer decides whether to allow it. They complement one another rather than replace one another.</p><h2 id="a-brief-introduction-to-x402" tabindex="-1">A brief introduction to x402 <a class="header-anchor" href="#a-brief-introduction-to-x402" aria-label="Permalink to &quot;A brief introduction to x402&quot;">​</a></h2><p>HTTP has a status code reserved long ago but rarely used: <strong>402 Payment Required</strong>. x402 puts it to work in a flow that broadly looks like this:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Buyer requests a resource.</span></span>
<span class="line"><span>2. Seller returns 402 with requirements such as price, recipient, asset, network, and expiry.</span></span>
<span class="line"><span>3. Buyer signs a payment authorization, includes it in the request, and retries.</span></span>
<span class="line"><span>4. Seller (or its facilitator) verifies the authorization and returns the resource.</span></span>
<span class="line"><span>5. The authorization is submitted for settlement, immediately or asynchronously.</span></span></code></pre></div><p>Payment happens as part of an HTTP request, without requiring an account, subscription, or prepaid balance. This can suit an agent that needs a service temporarily and pays per request without a person present.</p><p>AgentPay uses <strong>x402 V2</strong>. Two important headers are <code>PAYMENT-REQUIRED</code> (the seller&#39;s payment requirement) and <code>PAYMENT-SIGNATURE</code> (the buyer&#39;s signed authorization).</p><h2 id="an-important-fact-the-protocol-does-not-decide-whether-to-pay" tabindex="-1">An important fact: the protocol does not decide whether to pay <a class="header-anchor" href="#an-important-fact-the-protocol-does-not-decide-whether-to-pay" aria-label="Permalink to &quot;An important fact: the protocol does not decide whether to pay&quot;">​</a></h2><p>x402 addresses <strong>interoperability</strong>: buyers and sellers can exchange payment requirements and authorizations in a common format. It assumes the client knows when a payment is appropriate.</p><p>A basic protocol client may behave like this:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Receive 402 → parse requirements → sign → retry</span></span></code></pre></div><p>There is no step asking, “Wait, should I spend this money?” For example:</p><ul><li>The seller asks for 20 USDC, and the client signs.</li><li>The seller changes to an unfamiliar recipient, and the client signs.</li><li>A retry loop receives 402 repeatedly, and the client signs each time.</li></ul><p>There is nothing wrong with the protocol; this responsibility is simply outside its scope. <strong>That is division of responsibilities, not a protocol defect.</strong> But an autonomous agent that can make mistakes needs a component to perform this check.</p><h2 id="what-each-one-does" tabindex="-1">What each one does <a class="header-anchor" href="#what-each-one-does" aria-label="Permalink to &quot;What each one does&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>x402</th><th>AgentPay</th></tr></thead><tbody><tr><td><strong>Question answered</strong></td><td>How to pay</td><td>Whether to pay and what to do if it fails</td></tr><tr><td><strong>Layer</strong></td><td>Payment protocol</td><td>Financial control, with gateway, ledger, and audit capabilities around it</td></tr><tr><td><strong>Typical responsibilities</strong></td><td>Payment requirement format, authorization format, verification and settlement flow</td><td>Per-transaction caps, rolling budgets, allowlists, circuit breakers, atomic reservations, state recovery, audit</td></tr><tr><td><strong>Scope</strong></td><td>One payment exchange</td><td>An agent&#39;s spending behavior over time</td></tr><tr><td><strong>Stateful?</strong></td><td>Primarily a single exchange</td><td>Yes; tracks budgets, rates, and each payment&#39;s progress</td></tr><tr><td><strong>Defined by</strong></td><td>The open protocol community</td><td>The AgentPay project</td></tr></tbody></table><h2 id="how-they-work-together" tabindex="-1">How they work together <a class="header-anchor" href="#how-they-work-together" aria-label="Permalink to &quot;How they work together&quot;">​</a></h2><p>Here is where the two fit in one buyer-side x402 on-chain payment:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent requests a resource</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>Seller returns 402 + payment requirements       ← x402: requirement format</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────┐</span></span>
<span class="line"><span>│ AgentPay financial firewall          │       ← AgentPay: should it pay?</span></span>
<span class="line"><span>│ Per-call cap · budget · allowlist     │</span></span>
<span class="line"><span>│ circuit breaker                      │</span></span>
<span class="line"><span>└────────────┬────────────────┬───────┘</span></span>
<span class="line"><span>          Allow              Reject</span></span>
<span class="line"><span>            │                  │</span></span>
<span class="line"><span>            ▼                  └─▶ Do not sign; explain reason to agent</span></span>
<span class="line"><span>Reserve budget → sign authorization             ← x402: authorization format</span></span>
<span class="line"><span>            │</span></span>
<span class="line"><span>            ▼</span></span>
<span class="line"><span>Retry with PAYMENT-SIGNATURE                    ← x402</span></span>
<span class="line"><span>            │</span></span>
<span class="line"><span>            ▼</span></span>
<span class="line"><span>Seller verifies → returns resource → async settlement</span></span>
<span class="line"><span>            │</span></span>
<span class="line"><span>            ▼</span></span>
<span class="line"><span>AgentPay commits/releases reservation and audits ← AgentPay: recovery and trace</span></span></code></pre></div><p>AgentPay inserts a check <strong>before and after</strong> the x402 exchange: policy is evaluated before signing, and the reservation and audit are finalized after settlement progresses. The x402 format and flow remain unchanged, so the seller still sees a standard payment authorization.</p><h2 id="what-agentpay-adds-around-x402" tabindex="-1">What AgentPay adds around x402 <a class="header-anchor" href="#what-agentpay-adds-around-x402" aria-label="Permalink to &quot;What AgentPay adds around x402&quot;">​</a></h2><p><strong>1. Policy checks before payment.</strong> This is the core distinction; see <a href="./../04-agentpay-concepts/financial-firewall">Why We Need a Financial Firewall</a>.</p><p><strong>2. Budget protection under concurrency.</strong> The protocol does not record how much you have spent or coordinate a budget across concurrent requests; see <a href="./../04-agentpay-concepts/budget-reservation">Budget Reservation</a>.</p><p><strong>3. Handling failures afterward.</strong> What if payment succeeded but the response timed out? What if settlement is unknown? These cases are beyond the protocol&#39;s scope; see <a href="./../04-agentpay-concepts/timeout-is-not-failure">Timeout Is Not Failure</a>.</p><p><strong>4. A second payment rail.</strong> x402 is for on-chain payments. AgentPay also offers a platform virtual wallet: a request carrying an API key is charged to the tenant wallet without putting each payment on-chain, reducing latency. The credential determines which rail is used. <strong>Insufficient balance does not silently switch to an on-chain payment</strong>, avoiding unexpected spending.</p><p><strong>5. A paid API gateway and management.</strong> Turning an existing API into a paid endpoint, configuring prices and policies, publishing and rolling back changes, and reviewing usage and audit events are product capabilities around the protocol.</p><h2 id="does-agentpay-lock-you-in" tabindex="-1">Does AgentPay lock you in? <a class="header-anchor" href="#does-agentpay-lock-you-in" aria-label="Permalink to &quot;Does AgentPay lock you in?&quot;">​</a></h2><p>For the on-chain path, AgentPay follows x402 V2 formats and uses project test vectors to check encoding and signature consistency. Its core library does not depend strongly on a third-party x402 package; it implements the encoding and decoding according to the specification. If you also use an official library, optional interoperability utilities can convert between the two libraries&#39; objects.</p><p>The platform virtual-wallet path does not use x402 payment headers; it uses an API key. Therefore, “AgentPay” is not synonymous with “an x402 implementation.” x402 is one of the payment methods it supports.</p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><p><strong>Q: I already use x402. Why would I need AgentPay?</strong> If your agent runs in a controlled environment, has a small budget, and you monitor it, x402 may be enough. When an agent runs autonomously, handles concurrent requests, spends real money, or shares a budget with other agents, a control layer above the protocol becomes useful.</p><p><strong>Q: Can I write my own checks around an x402 client?</strong> Yes. A simple per-call cap is straightforward. Correct concurrent budget accounting, timeout handling after signing, circuit breaking, and audit involve many details; AgentPay aims to provide these together.</p><p><strong>Q: Does AgentPay replace x402?</strong> No. The on-chain payment path relies on x402. AgentPay adds value above the protocol rather than replacing it.</p><p><strong>Q: Does AgentPay interoperate with every x402 seller?</strong> AgentPay implements x402 V2 and validates it with protocol test vectors. Interoperability with third-party implementations still needs to be confirmed through practical testing. The project is experimental.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>To see AgentPay&#39;s full place in the system: <a href="./where-agentpay-fits">Where AgentPay Fits</a></li><li>To understand HTTP 402 and x402: <a href="./../02-agent-payments/http-402-and-x402">HTTP 402 and x402</a></li><li>To see both work together: <a href="./../05-hands-on/ten-minute-demo">10-Minute Demo</a></li></ul><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="/docs/specs/protocol-consistency">Protocol Consistency Contract</a>: payment headers, dual-rail decisions, and error codes.</li><li><a href="/docs/specs/adr-001">ADR-001: Reusing x402 vs. Implementing It In-House</a>: why the core library implements protocol encoding and decoding itself.</li></ul>`,41)])])}const g=a(o,[["render",r]]);export{u as __pageData,g as default};
